-- ============================================================
--  IL VAGONE FANTASMA DELLA LINEA MENTA
--  Un giallo da risolvere con SQL · Corso intensivo di coding · Giorno 4
--
--  Per caricarlo:
--      createdb giallo
--      psql -d giallo -f giallo.sql
--
--  I testi degli indizi sono sigillati: aprire questo file non serve.
--  Le risposte stanno nel database. Si trovano con le query.
-- ============================================================

SET client_min_messages = warning;
DROP TABLE IF EXISTS bonifici, telefonate, telefoni, interrogatori, ferie, accessi_badge, dipendenti,
    licenze_artisti, testimonianze, verbali, tornelli, abbonamenti, persone CASCADE;

CREATE TABLE persone (
    id           INTEGER PRIMARY KEY,
    nome         TEXT NOT NULL,
    cognome      TEXT NOT NULL,
    via          TEXT NOT NULL,
    civico       INTEGER NOT NULL,
    professione  TEXT NOT NULL
);

CREATE TABLE abbonamenti (
    codice       TEXT PRIMARY KEY,
    persona_id   INTEGER NOT NULL REFERENCES persone(id),
    tipo         TEXT NOT NULL CHECK (tipo IN ('annuale', 'mensile', 'settimanale')),
    scadenza     DATE NOT NULL
);

CREATE TABLE tornelli (
    id           SERIAL PRIMARY KEY,
    abbonamento  TEXT NOT NULL REFERENCES abbonamenti(codice),
    stazione     TEXT NOT NULL,
    data         DATE NOT NULL,
    ora          TIME NOT NULL,
    verso        TEXT NOT NULL CHECK (verso IN ('entrata', 'uscita'))
);

CREATE TABLE verbali (
    id           SERIAL PRIMARY KEY,
    data         DATE NOT NULL,
    ora          TIME NOT NULL,
    luogo        TEXT NOT NULL,
    tipo         TEXT NOT NULL,
    descrizione  TEXT NOT NULL
);

CREATE TABLE testimonianze (
    id           SERIAL PRIMARY KEY,
    persona_id   INTEGER NOT NULL REFERENCES persone(id),
    data         DATE NOT NULL,
    testo        TEXT NOT NULL
);

CREATE TABLE licenze_artisti (
    id           SERIAL PRIMARY KEY,
    persona_id   INTEGER NOT NULL REFERENCES persone(id),
    stazione     TEXT NOT NULL,
    strumento    TEXT NOT NULL
);

CREATE TABLE dipendenti (
    matricola    TEXT PRIMARY KEY,
    persona_id   INTEGER NOT NULL UNIQUE REFERENCES persone(id),
    ruolo        TEXT NOT NULL,
    squadra      TEXT NOT NULL,
    badge        TEXT NOT NULL UNIQUE
);

CREATE TABLE accessi_badge (
    id           SERIAL PRIMARY KEY,
    badge        TEXT NOT NULL REFERENCES dipendenti(badge),
    stazione     TEXT NOT NULL,
    data         DATE NOT NULL,
    ora          TIME NOT NULL,
    porta        TEXT NOT NULL
);

CREATE TABLE ferie (
    id           SERIAL PRIMARY KEY,
    matricola    TEXT NOT NULL REFERENCES dipendenti(matricola),
    dal          DATE NOT NULL,
    al           DATE NOT NULL,
    destinazione TEXT NOT NULL
);

CREATE TABLE interrogatori (
    id           SERIAL PRIMARY KEY,
    persona_id   INTEGER NOT NULL REFERENCES persone(id),
    data         DATE NOT NULL,
    testo        TEXT NOT NULL
);

CREATE TABLE telefoni (
    numero       TEXT PRIMARY KEY,
    persona_id   INTEGER NOT NULL REFERENCES persone(id),
    tipo         TEXT NOT NULL CHECK (tipo IN ('fisso', 'cellulare'))
);

CREATE TABLE telefonate (
    id           SERIAL PRIMARY KEY,
    chiamante    TEXT NOT NULL REFERENCES telefoni(numero),
    ricevente    TEXT NOT NULL REFERENCES telefoni(numero),
    data         DATE NOT NULL,
    ora          TIME NOT NULL,
    durata_sec   INTEGER NOT NULL
);

CREATE TABLE bonifici (
    id           SERIAL PRIMARY KEY,
    da_persona   INTEGER NOT NULL REFERENCES persone(id),
    a_persona    INTEGER NOT NULL REFERENCES persone(id),
    data         DATE NOT NULL,
    importo      NUMERIC(10, 2) NOT NULL,
    causale      TEXT NOT NULL
);


