-- ------------------------------------------------------------
--  Per controllare le vostre conclusioni:
--      SELECT verifica('Nome Cognome');
--      SELECT verifica_mandante('Nome Cognome');
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION verifica(sospettato TEXT) RETURNS TEXT
LANGUAGE sql STABLE AS $$
    SELECT CASE
        WHEN md5(lower(regexp_replace(trim(sospettato), '\s+', ' ', 'g'))) IN ('af2098983cc110dd3cde0dfa9c5a7890', 'f55615d1e682c8cfa373152db694520f') THEN convert_from(decode('RVNBVFRPISBJbCBjb21taXNzYXJpbyBNYXBlbGxpIHBvc2EgaWwgY2FmZsOoIGUgdmkgc3RyaW5nZSBsYSBtYW5vLiBNZXNzbyBhbGxlIHN0cmV0dGUsIGlsIGNvbHBldm9sZSBjb25mZXNzYTogwqtWYSBiZW5lLCB2YSBiZW5lLiBIbyBzdGFjY2F0byBpbyBpbCB2YWdvbmUgZSBobyBnaXJhdG8gbG8gc2NhbWJpbyB2ZXJzbyBWZWNjaGlhIEZpZXJhLCBjb2wgYmFkZ2UgZGkgVWdvLiBNYSBpbCBsYXZvcm8gbWUgbCdoYW5ubyBjb21taXNzaW9uYXRvLiBJbCBub21lIG5vbiBsbyBzbzogbWkgY2hpYW1hdmEgc2VtcHJlIGRhIHVuIG51bWVybyBmaXNzbywgc2VtcHJlIGRvcG8gbGUgZGllY2kgZGkgc2VyYSwgZSBsZSB0ZWxlZm9uYXRlIGR1cmF2YW5vIHBvY2hpc3NpbW8sIG1lbm8gZGkgdW4gbWludXRvLiBNaSBoYSBwYWdhdG8gY29uIHRyZSBib25pZmljaS4gRGljZXZhIHNvbG86IGlsIHJpc290dG8gZGV2ZSB0b3JuYXJlIGEgY2hpIGxvIG1lcml0YS7CuyBDaGkgw6ggaWwgbWFuZGFudGU/IFF1YW5kbyBsbyBzYXBldGU6IFNFTEVDVCB2ZXJpZmljYV9tYW5kYW50ZSgnTm9tZSBDb2dub21lJyk7', 'base64'), 'UTF8')
        WHEN md5(lower(regexp_replace(trim(sospettato), '\s+', ' ', 'g'))) IN ('c2e7ce603dba767d9ccc3ae99f0a42dd', 'b62b5826e60a65bb1a0d40f134735e23') THEN convert_from(decode('Q2kgc2lldGUgdmljaW5pOiBxdWVzdGEgcGVyc29uYSBjJ2VudHJhIGVjY29tZSwgbWEgaWwgdmFnb25lIG5vbiBsJ2hhIHN0YWNjYXRvIGxlaS4gQ2hpIGVyYSBhIGJvcmRvPw==', 'base64'), 'UTF8')
        ELSE convert_from(decode('Tm8uIElsIGNvbW1pc3NhcmlvIE1hcGVsbGkgc29zcGlyYSwgZ3VhcmRhIGlsIHNvZmZpdHRvIGUgdmkgcmltYW5kYSBhZ2xpIGluZGl6aS4=', 'base64'), 'UTF8')
    END
$$;

CREATE OR REPLACE FUNCTION verifica_mandante(sospettato TEXT) RETURNS TEXT
LANGUAGE sql STABLE AS $$
    SELECT CASE
